{"query": "WITH sg AS (
  SELECT Gene AS ensembl, TRY_CAST(nTPM AS DOUBLE) AS sg_ntpm
  FROM rna_tissue_consensus WHERE Tissue = 'salivary gland'
),
cohort AS (
  SELECT p.Ensembl, p."Secretome location" AS sec
  FROM sg JOIN proteinatlas p ON p.Ensembl = sg.ensembl
  WHERE sg.sg_ntpm >= 1
)
SELECT COUNT(*) AS secreted_blood_cohort FROM cohort WHERE sec='Secreted to blood'"}
